        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    def is_hex_digit(char):
        hex_digits = "0123456789ABCDEF"
        return char in hex_digits

    prime_hex_count = 0
    for char in num:
        if is_hex_digit(char):
            if char.isdigit():
                if int(char) in [2, 3, 5, 7]:
                    prime_hex_count += 1
            else:
                if char in ['B', 'D']:
                    prime_hex_count += 1

    return prime_hex_count

