        return "Input string must contain only alphabetical characters."

    s = s.lower()

    vowels = ['a', 'e', 'i', 'o', 'u']
    count = 0
    for i in range(len(s)):
        if s[i] in vowels or (s[i] == 'y' and i == len(s) - 1):
            count += 1

    return count

